CREATE OR REPLACE FUNCTION pharmflow_expiry_private.guard_photo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare v_path text;v_op pharmflow_expiry_private.operations%rowtype;v_photo pharmflow_expiry_private.photos%rowtype;v_p uuid;v_id uuid;v_actor uuid;v_member boolean;v_prior_sub text;
begin
 if tg_op='UPDATE' then
  if (old.bucket_id='pharmflow-needs-review' and split_part(old.name,'/',2)='expiry-v1') or (new.bucket_id='pharmflow-needs-review' and split_part(new.name,'/',2)='expiry-v1') then raise exception 'Expiry photos are immutable; retake with a new path';end if;
  return new;
 end if;
 if tg_op='DELETE' then v_path:=old.name;if old.bucket_id<>'pharmflow-needs-review' or split_part(v_path,'/',2)<>'expiry-v1' then return old;end if;
 else v_path:=new.name;if new.bucket_id<>'pharmflow-needs-review' or split_part(v_path,'/',2)<>'expiry-v1' then return new;end if;end if;
 if v_path !~ '^[0-9a-f-]{36}/expiry-v1/[0-9a-f-]{36}/(product|expiry)/[0-9a-f-]{36}\.(jpg|png|webp)$' then raise exception 'Invalid Expiry photo path';end if;
 v_p:=split_part(v_path,'/',1)::uuid;v_id:=split_part(v_path,'/',3)::uuid;
 select * into v_op from pharmflow_expiry_private.operations where pharmacy_id=v_p and operation_id=v_id for update;
 if not found then raise exception 'Photo scope denied';end if;
 if tg_op='DELETE' and current_setting('role',true)='service_role' and exists(
  select 1 from pharmflow_expiry_private.photo_cleanup_jobs j
  where j.pharmacy_id=v_p and j.operation_id=v_id and j.object_path=v_path
    and j.state='CLAIMED' and j.claim_until>now() and j.claim_token is not null
    and pharmflow_expiry_private.photo_cleanup_eligible(j.pharmacy_id,j.operation_id,j.review_id,j.object_path,j.cleanup_reason)
 ) then
  update pharmflow_expiry_private.photos set deleted_at=coalesce(deleted_at,now()),cleanup_by=null,cleanup_until=null where path=v_path and pharmacy_id=v_p and operation_id=v_id;
  return old;
 end if;
 v_actor:=auth.uid();
 if tg_op='INSERT' and v_actor is null and session_user='supabase_storage_admin' and current_setting('role',true)='service_role' then
  v_actor:=coalesce(new.owner_id,new.owner::text)::uuid;v_prior_sub:=current_setting('request.jwt.claim.sub',true);perform set_config('request.jwt.claim.sub',v_actor::text,true);v_member:=public.is_pharmacy_member(v_p);perform set_config('request.jwt.claim.sub',coalesce(v_prior_sub,''),true);
 else v_member:=public.is_pharmacy_member(v_p);end if;
 if v_actor is null or v_member is not true then raise exception 'Photo scope denied';end if;
 if tg_op='INSERT' then
  if v_op.status<>'RESERVED' or v_op.created_by<>v_actor or coalesce(new.owner_id,new.owner::text) is distinct from v_actor::text then raise exception 'Photo upload denied';end if;
  if session_user='supabase_storage_admin' and (new.metadata->>'mimetype' is null or new.metadata->>'size' is null) then return new;end if;
  if new.metadata->>'mimetype' is null or new.metadata->>'mimetype' not in ('image/jpeg','image/png','image/webp') or coalesce((new.metadata->>'size')::bigint,0) not between 1 and 5242880 then raise exception 'Invalid photo type or size';end if;
  insert into pharmflow_expiry_private.photos(path,pharmacy_id,operation_id,role,created_by) values(v_path,v_p,v_id,split_part(v_path,'/',4),v_actor);return new;
 end if;
 select * into v_photo from pharmflow_expiry_private.photos where path=v_path;
 if v_op.status='RESERVED' and v_photo.created_by=auth.uid() then update pharmflow_expiry_private.photos set deleted_at=now() where path=v_path;return old;end if;
 if v_op.status<>'COMMITTED' or public.is_pharmacy_admin(v_p) is not true or v_photo.cleanup_by is distinct from auth.uid() or v_photo.cleanup_until is null or v_photo.cleanup_until<now()
   or not exists(select 1 from pharmflow_expiry_private.review_details d join public.pharmflow_needs_review_v2 r on r.id=d.review_id where d.pharmacy_id=v_p and d.operation_id=v_id and r.workflow='EXPIRY' and r.status='RESOLVED') then raise exception 'Resolved Expiry cleanup authorization required';end if;
 update pharmflow_expiry_private.photos set deleted_at=now(),cleanup_by=null,cleanup_until=null where path=v_path;return old;
end $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.fail_photo_cleanup_job(p_job_id uuid, p_claim_token uuid, p_error_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pharmflow_expiry_private', 'pg_temp'
AS $function$
begin
 if current_setting('role',true)<>'service_role' then raise exception 'Cleanup worker role required';end if;
 update pharmflow_expiry_private.photo_cleanup_jobs set state='FAILED',claim_until=null,claim_token=null,next_attempt_at=now()+make_interval(secs=>least(3600,5*(2^least(attempts,9))::integer)),last_error_code=left(coalesce(nullif(p_error_code,''),'storage_error'),64)
 where job_id=p_job_id and claim_token=p_claim_token and state='CLAIMED' and claim_until>now();
 return found;
end $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.guard_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
begin
 if tg_op='INSERT' then
  if new.workflow='EXPIRY' and not exists(select 1 from pharmflow_expiry_private.operations o where o.pharmacy_id=new.pharmacy_id and o.operation_id::text=new.operation_id and o.created_by=auth.uid() and o.status='COMMITTING' and o.payload->>'kind'='UNKNOWN') then raise exception 'Expiry review requires complete operation capture';end if;
  if new.deleted_by is not null or new.deleted_at is not null then raise exception 'Deletion attribution is server managed';end if;
  return new;
 end if;
 if old.workflow<>'EXPIRY' then
  if tg_op='UPDATE' and new.workflow='EXPIRY' then raise exception 'Workflow reassignment denied';end if;
  if tg_op='DELETE' then return old;else return new;end if;
 end if;
 if not exists(select 1 from pharmflow_expiry_private.review_details where review_id=old.id) then
  if tg_op='DELETE' then return old;else return new;end if;
 end if;
 if tg_op='DELETE' then raise exception 'Expiry review audit cannot be deleted';end if;
 if row(new.id,new.created_at,new.review_reason,new.pharmacy_id,new.workflow,new.gtin,new.identifier_display,new.identifier_key,new.raw_barcode,new.pending_quantity,new.source,new.device_id,new.created_by,new.operation_id,new.photo_path) is distinct from row(old.id,old.created_at,old.review_reason,old.pharmacy_id,old.workflow,old.gtin,old.identifier_display,old.identifier_key,old.raw_barcode,old.pending_quantity,old.source,old.device_id,old.created_by,old.operation_id,old.photo_path) then raise exception 'Expiry capture evidence is immutable';end if;
 if new.status='DELETED' and old.status='PENDING' then
  if public.is_pharmacy_member(old.pharmacy_id) is not true or new.deleted_by is distinct from auth.uid() or new.deleted_at is null or new.resolved_by is distinct from old.resolved_by or new.resolved_item_code is distinct from old.resolved_item_code or new.resolved_item_name is distinct from old.resolved_item_name then raise exception 'Authorized pharmacy-member pending-case deletion required';end if;
  if old.deleted_by is not null or old.deleted_at is not null then raise exception 'Deletion attribution is immutable';end if;
  return new;
 end if;
 if old.status='DELETED' then raise exception 'Deleted Expiry review is immutable';end if;
 if new.deleted_by is distinct from old.deleted_by or new.deleted_at is distinct from old.deleted_at then raise exception 'Deletion attribution is immutable';end if;
 if new.status=old.status and row(new.resolved_by,new.resolved_item_code,new.resolved_item_name) is distinct from row(old.resolved_by,old.resolved_item_code,old.resolved_item_name) then raise exception 'Resolution attribution is immutable outside successful resolution';end if;
 if new.status is distinct from old.status and (old.status<>'PENDING' or new.status<>'RESOLVED' or public.is_pharmacy_member(old.pharmacy_id) is not true or new.resolved_by is distinct from auth.uid() or coalesce(btrim(new.resolved_item_code),'')='' or coalesce(btrim(new.resolved_item_name),'')='') then raise exception 'Authorized successful resolution required';end if;
 return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.protect_system_operator_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if TG_OP='DELETE' then
  if old.system_key is not null then raise exception 'Built-in Operators cannot be removed';end if;
  return old;
 end if;
 if TG_OP='UPDATE' and old.system_key is not null and
   (new.worker_name is distinct from old.worker_name or new.active is distinct from old.active or new.pharmacy_id is distinct from old.pharmacy_id or new.system_key is distinct from old.system_key) then
   raise exception 'Built-in Operators cannot be changed';
 end if;
 if new.system_key is null and lower(btrim(new.worker_name)) in ('desktop','handheld') then raise exception 'This name is reserved for a built-in Operator';end if;
 if new.system_key is not null and (new.worker_name<>case new.system_key when 'DESKTOP' then 'Desktop' else 'Handheld' end or new.active is not true) then raise exception 'Invalid built-in Operator';end if;
 return new;
end $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.save_known_core(p_pharmacy_id uuid, p_item_code text, p_item_name text, p_identifier_display text, p_category text, p_quantity integer, p_expiry_month integer, p_expiry_year integer, p_worker_id uuid DEFAULT NULL::uuid, p_batch_no text DEFAULT NULL::text, p_sample_serial text DEFAULT NULL::text, p_device_id text DEFAULT NULL::text, p_source text DEFAULT 'HANDHELD'::text, p_event_type text DEFAULT 'CAPTURE'::text)
 RETURNS TABLE(state_id uuid, event_id uuid, last_verified_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 v_user uuid:=auth.uid(); v_worker_name text; v_identifier_display text:=btrim(coalesce(p_identifier_display,''));
 v_identifier_key text; v_item_code text:=btrim(coalesce(p_item_code,'')); v_item_name text:=btrim(coalesce(p_item_name,''));
 v_batch_no text:=nullif(coalesce(p_batch_no,''),''); v_batch_key text:=coalesce(nullif(upper(btrim(coalesce(p_batch_no,''))),''),'');
 v_source text:=upper(btrim(coalesce(p_source,'HANDHELD'))); v_event_type text:=upper(btrim(coalesce(p_event_type,'CAPTURE')));
 v_state_id uuid; v_event_id uuid; v_previous_quantity integer; v_new_quantity integer; v_now timestamptz:=now();
begin
 if v_user is null or not public.is_pharmacy_member(p_pharmacy_id) then raise exception 'Pharmacy access required'; end if;
 if v_item_code='' or v_item_name='' or v_identifier_display='' then raise exception 'Item Code, Item Name and Identifier are required'; end if;
 v_identifier_key:=public.pharmflow_identifier_key_v2(v_identifier_display);
 if nullif(v_identifier_key,'') is null then raise exception 'Identifier is invalid'; end if;
 if p_quantity is null or p_quantity<0 then raise exception 'Quantity cannot be negative'; end if;
 if p_expiry_month not between 1 and 12 or p_expiry_year not between 2020 and 2200 then raise exception 'Expiry date is invalid'; end if;
 if v_source not in ('HANDHELD','PC') then raise exception 'Invalid expiry source'; end if;
 if v_event_type not in ('CAPTURE','RECOUNT','CLEARED') then raise exception 'Invalid expiry event type'; end if;
 if (v_event_type='CLEARED' and p_quantity<>0) or (v_event_type<>'CLEARED' and p_quantity=0) then raise exception 'Invalid zero quantity event'; end if;
 if p_worker_id is not null then
   select w.worker_name into v_worker_name from public.pharmflow_expiry_workers_v1 w
   where w.id=p_worker_id and w.pharmacy_id=p_pharmacy_id;
   if v_worker_name is null then raise exception 'Historical pharmacy Operator unavailable'; end if;
 elsif v_source='HANDHELD' then raise exception 'Select an active worker before saving';
 else v_worker_name:='Desktop';
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_pharmacy_id::text||'/item/'||v_item_code||'/'||v_batch_key||'/'||p_expiry_year::text||'/'||p_expiry_month::text,0));
 select s.id,s.verified_quantity into v_state_id,v_previous_quantity from public.pharmflow_expiry_current_state_v1 s
 where s.pharmacy_id=p_pharmacy_id and s.item_code=v_item_code and s.batch_key=v_batch_key
 and s.expiry_year=p_expiry_year and s.expiry_month=p_expiry_month for update;
 if v_event_type='CAPTURE' then v_new_quantity:=coalesce(v_previous_quantity,0)+p_quantity;
 elsif v_event_type='RECOUNT' then v_new_quantity:=p_quantity; else v_new_quantity:=0; end if;
 if v_state_id is null then
  insert into public.pharmflow_expiry_current_state_v1(pharmacy_id,item_code,item_name,identifier_display,identifier_key,category,batch_no,batch_key,sample_serial,expiry_month,expiry_year,verified_quantity,worker_id,verified_by_name,verified_by_user_id,last_verified_at,device_id,source,status)
  values(p_pharmacy_id,v_item_code,v_item_name,v_identifier_display,v_identifier_key,nullif(btrim(coalesce(p_category,'')),''),v_batch_no,v_batch_key,nullif(btrim(coalesce(p_sample_serial,'')),''),p_expiry_month,p_expiry_year,v_new_quantity,p_worker_id,v_worker_name,v_user,v_now,nullif(btrim(coalesce(p_device_id,'')),''),v_source,case when v_new_quantity=0 then 'CLEARED' else 'ACTIVE' end)
  returning id into v_state_id;
 else
  update public.pharmflow_expiry_current_state_v1 set item_name=v_item_name,identifier_display=v_identifier_display,identifier_key=v_identifier_key,
  category=nullif(btrim(coalesce(p_category,'')),''),batch_no=case when v_event_type='CAPTURE' then coalesce(batch_no,v_batch_no) else v_batch_no end,sample_serial=nullif(btrim(coalesce(p_sample_serial,'')),''),
  verified_quantity=v_new_quantity,worker_id=p_worker_id,verified_by_name=v_worker_name,verified_by_user_id=v_user,last_verified_at=v_now,
  device_id=nullif(btrim(coalesce(p_device_id,'')),''),source=v_source,status=case when v_new_quantity=0 then 'CLEARED' else 'ACTIVE' end,updated_at=v_now where id=v_state_id;
 end if;
 insert into public.pharmflow_expiry_events_v1(state_id,pharmacy_id,event_type,item_code,item_name,identifier_display,identifier_key,category,batch_no,sample_serial,expiry_month,expiry_year,previous_quantity,verified_quantity,worker_id,verified_by_name,verified_by_user_id,device_id,source,occurred_at)
 values(v_state_id,p_pharmacy_id,v_event_type,v_item_code,v_item_name,v_identifier_display,v_identifier_key,nullif(btrim(coalesce(p_category,'')),''),v_batch_no,nullif(btrim(coalesce(p_sample_serial,'')),''),p_expiry_month,p_expiry_year,v_previous_quantity,v_new_quantity,p_worker_id,v_worker_name,v_user,nullif(btrim(coalesce(p_device_id,'')),''),v_source,v_now) returning id into v_event_id;
 return query select v_state_id,v_event_id,v_now;
end $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.scan_facts(p_raw text, p_format text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare s text:=btrim(p_raw,E' \r\n\t');v_ai text;v_value text;v_facts jsonb:='{}';v_stop integer;v_fixed integer;v_year integer;v_month integer;v_day integer;
begin
 if s is null or s='' then raise exception 'Raw scan required';end if;
 if s ~ '^\][A-Za-z][0-9]' then s:=substr(s,4);end if;
 if p_format='PLAIN' then return jsonb_build_object('identifier',s);end if;
 if p_format is distinct from 'GS1' then raise exception 'Invalid scan format';end if;
 while length(s)>0 loop
  if left(s,1)=chr(29) then s:=substr(s,2);continue;end if;
  if left(s,1)='(' then
   if s !~ '^\((01|11|17|10|21)\)' then raise exception 'Unsupported GS1 AI';end if;
   v_ai:=substr(s,2,2);s:=substr(s,5);v_stop:=strpos(s,'(');if v_stop=0 then v_stop:=length(s)+1;end if;
   v_value:=substr(s,1,v_stop-1);s:=substr(s,v_stop);
  else
   v_ai:=left(s,2);s:=substr(s,3);v_fixed:=case v_ai when '01' then 14 when '11' then 6 when '17' then 6 else null end;
   if v_ai not in ('01','11','17','10','21') then raise exception 'Unsupported GS1 AI';end if;
   if v_fixed is not null then v_value:=left(s,v_fixed);s:=substr(s,v_fixed+1);
   else v_stop:=strpos(s,chr(29));if v_stop=0 then v_stop:=length(s)+1;end if;v_value:=left(s,v_stop-1);s:=substr(s,v_stop);end if;
  end if;
  if v_facts ? v_ai then raise exception 'Duplicate GS1 AI';end if;
  if (v_ai='01' and v_value !~ '^[0-9]{14}$') or (v_ai in ('11','17') and v_value !~ '^[0-9]{6}$') or (v_ai in ('10','21') and length(v_value) not between 1 and 20) then raise exception 'Invalid GS1 value';end if;
  if v_ai='11' then
   v_year:=2000+left(v_value,2)::integer;v_month:=substr(v_value,3,2)::integer;v_day:=right(v_value,2)::integer;
   if v_day=0 then raise exception 'GS1 production date requires a day';end if;
   begin perform make_date(v_year,v_month,v_day);
   exception when datetime_field_overflow then raise exception 'Invalid GS1 production date';end;
  end if;
  v_facts:=v_facts||jsonb_build_object(v_ai,v_value);
 end loop;
 if not v_facts ? '01' then raise exception 'GS1 GTIN required';end if;
 if v_facts ? '11' and not v_facts ? '17' then raise exception 'GS1 expiry AI 17 required with production date';end if;
 return v_facts||jsonb_build_object('identifier',v_facts->>'01');
end $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.valid_auth_session()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare sid uuid;j jsonb:=auth.jwt();
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 sid:=nullif(j->>'session_id','')::uuid;
 if sid is null or coalesce((j->>'exp')::numeric,0)<=extract(epoch from now()) or not exists(select 1 from auth.sessions s where s.id=sid and s.user_id=auth.uid() and (s.not_after is null or s.not_after>now())) then raise exception 'Authentication session expired or revoked';end if;
 return sid;
end $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.batch_is_scanner_payload(p_value text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare s text:=btrim(coalesce(p_value,'')); facts jsonb; marked boolean;
begin
 s:=regexp_replace(s,E'[\r\n\t]','','g');
 s:=regexp_replace(s,'(<GS>|\\u001D|\\x1D)',chr(29),'gi');
 s:=translate(s,chr(28)||chr(30)||chr(31)||chr(9245)||chr(65533)||chr(1617),repeat(chr(29),6));
 s:=replace(s,E'\\~',chr(29));s:=regexp_replace(s,'~+',chr(29),'g');
 marked:=s ~* '^\](C1|d2|Q3)' or strpos(s,chr(29))>0 or left(s,4)='(01)';
 begin
  facts:=pharmflow_expiry_private.scan_facts(s,'GS1');
  if facts ? '01' and facts ?| array['10','11','17','21'] then return true; end if;
 exception when others then null; -- Only classification fails; no business write occurs.
 end;
 s:=regexp_replace(s,'^\][A-Za-z][0-9]','');
 return marked and s ~ ('^(01[0-9]{14}(11|17|10|21|'||chr(29)||')|\(01\)[0-9]{14}\((11|17|10|21)\))');
end $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.gs1_source_locks(p_payload jsonb, p_facts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare f jsonb;batch_locked boolean:=false;expiry_locked boolean:=false;
begin
 if p_facts ? 'correction_source' and not(p_facts ? 'gs1_source_locks') then return jsonb_build_object('batch',false,'expiry',false);end if;
 if p_payload->>'scan_format' is distinct from 'GS1' then return jsonb_build_object('batch',false,'expiry',false);end if;
 begin f:=pharmflow_expiry_private.scan_facts(p_payload->>'raw_scan','GS1');exception when others then return jsonb_build_object('batch',false,'expiry',false);end;
 batch_locked:=f ? '10' and f->>'10'=p_payload->>'batch_no' and coalesce(p_facts->>'batch_no',p_payload->>'batch_no','')=f->>'10';
 expiry_locked:=f ? '17' and (substr(f->>'17',3,2))::integer=(p_payload->>'expiry_month')::integer and 2000+(left(f->>'17',2))::integer=(p_payload->>'expiry_year')::integer
 and coalesce(p_facts->>'expiry_month',p_payload->>'expiry_month')=p_payload->>'expiry_month' and coalesce(p_facts->>'expiry_year',p_payload->>'expiry_year')=p_payload->>'expiry_year';
 if p_facts ? 'gs1_source_locks' then batch_locked:=batch_locked and coalesce((p_facts->'gs1_source_locks'->>'batch')::boolean,false);expiry_locked:=expiry_locked and coalesce((p_facts->'gs1_source_locks'->>'expiry')::boolean,false);end if;
 return jsonb_build_object('batch',coalesce(batch_locked,false),'expiry',coalesce(expiry_locked,false));
end $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.record_operation_operator_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare e public.pharmflow_expiry_events_v1%rowtype;
begin
 if new.status='COMMITTED' and new.payload->>'kind'='KNOWN' and new.result->>'event_id' is not null then
 select * into e from public.pharmflow_expiry_events_v1 where id=(new.result->>'event_id')::uuid and pharmacy_id=new.pharmacy_id;
 if found then perform pharmflow_expiry_private.keep_operator_origin_v1(e.state_id,e.pharmacy_id,e.id,(new.payload->>'worker_id')::uuid,e.verified_by_name,new.created_at);end if;
 end if;return new;
end $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.record_review_operator_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r record;
begin
 select op.payload,op.created_at,d.worker_name into r from pharmflow_expiry_private.review_details d join pharmflow_expiry_private.operations op on op.pharmacy_id=d.pharmacy_id and op.operation_id=d.operation_id
 where d.review_id=new.review_id and d.pharmacy_id=new.pharmacy_id;
 if found then perform pharmflow_expiry_private.keep_operator_origin_v1(new.expiry_state_id,new.pharmacy_id,new.expiry_event_id,(r.payload->>'worker_id')::uuid,r.worker_name,r.created_at);end if;
 return new;
end $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.require_signed_session(p_pharmacy_id uuid, p_session_id uuid, p_open boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare sid uuid:=pharmflow_expiry_private.valid_auth_session();s pharmflow_expiry_private.active_sessions_v1%rowtype;
begin
 if public.is_pharmacy_member(p_pharmacy_id) is not true then raise exception 'Pharmacy access required';end if;
 select * into s from pharmflow_expiry_private.active_sessions_v1 where id=p_session_id for update;
 if not found or s.pharmacy_id<>p_pharmacy_id or s.created_by<>auth.uid() or s.auth_session_id is distinct from sid then raise exception 'Signed session scope mismatch';end if;
 if p_open and s.closed_at is not null then raise exception 'Session closed';end if;
end $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.guard_photo_operation_cleanup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 IF OLD.status='CANCELLED' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Cancelled operation is permanently fenced'; END IF;
 IF OLD.status='COMMITTED' AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.payload IS DISTINCT FROM OLD.payload) THEN RAISE EXCEPTION 'Committed photo references are immutable'; END IF;
 RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.complete_photo_cleanup_job(p_job_id uuid, p_object_path text, p_claim_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pharmflow_expiry_private', 'pg_temp'
AS $function$
DECLARE j pharmflow_expiry_private.photo_cleanup_jobs%rowtype;
BEGIN
 IF current_setting('role',true)<>'service_role' THEN RAISE EXCEPTION 'Cleanup worker role required'; END IF;
 SELECT * INTO j FROM pharmflow_expiry_private.photo_cleanup_jobs WHERE job_id=p_job_id AND object_path=p_object_path AND claim_token=p_claim_token AND state='CLAIMED' AND claim_until>now() FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 IF NOT pharmflow_expiry_private.photo_cleanup_eligible(j.pharmacy_id,j.operation_id,j.review_id,j.object_path,j.cleanup_reason) THEN RAISE EXCEPTION 'Cleanup target is not eligible'; END IF;
 IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='pharmflow-needs-review' AND name=p_object_path) THEN RAISE EXCEPTION 'Storage object still exists'; END IF;
 UPDATE pharmflow_expiry_private.photos SET deleted_at=coalesce(deleted_at,now()),cleanup_by=NULL,cleanup_until=NULL WHERE path=p_object_path AND pharmacy_id=j.pharmacy_id AND operation_id=j.operation_id;
 UPDATE pharmflow_expiry_private.photo_cleanup_jobs SET state='DONE',claim_until=NULL,claim_token=NULL,completed_at=coalesce(completed_at,now()),last_error_code=NULL WHERE job_id=p_job_id AND claim_token=p_claim_token;
 RETURN true;
END $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.enqueue_receiving_review_photos(p_pharmacy uuid, p_review uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE r public.pharmflow_needs_review_v2%rowtype; n integer;
BEGIN
 SELECT * INTO r FROM public.pharmflow_needs_review_v2 WHERE id=p_review AND pharmacy_id=p_pharmacy AND workflow='RECEIVING' AND status IN ('RESOLVED','DELETED') FOR UPDATE;
 IF NOT FOUND THEN RETURN 0; END IF;
 INSERT INTO pharmflow_expiry_private.photo_cleanup_jobs(pharmacy_id,review_id,operation_id,object_path,cleanup_reason)
 SELECT p_pharmacy,p_review,NULL,q.path,'TERMINAL' FROM (
  SELECT o.name path FROM storage.objects o WHERE o.bucket_id='pharmflow-needs-review' AND o.name LIKE p_pharmacy::text||'/'||p_review::text||'/%'
  UNION SELECT r.photo_path WHERE r.photo_path IS NOT NULL
 ) q WHERE q.path ~ ('^'||p_pharmacy::text||'/'||p_review::text||'/[0-9]{10,20}[.](jpg|png|webp)$')
 ON CONFLICT(object_path) DO NOTHING;
 GET DIAGNOSTICS n=ROW_COUNT; RETURN n;
END $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.receiving_review_photo_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
 IF NEW.workflow='RECEIVING' AND NEW.status IN ('RESOLVED','DELETED') THEN
  PERFORM pharmflow_expiry_private.enqueue_receiving_review_photos(NEW.pharmacy_id,NEW.id);
 END IF;
 RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.guard_receiving_review_photo_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
 IF NEW.workflow<>'RECEIVING' THEN RETURN NEW; END IF;
 IF NEW.photo_path IS NOT NULL AND (TG_OP='INSERT' OR NEW.photo_path IS DISTINCT FROM OLD.photo_path) AND
  NEW.photo_path !~ ('^'||NEW.pharmacy_id::text||'/'||NEW.id::text||'/[0-9]{10,20}[.](jpg|png|webp)$') THEN
  RAISE EXCEPTION 'Receiving photo reference must belong to this review and pharmacy';
 END IF;
 IF NEW.status='PENDING' AND NEW.photo_path IS NOT NULL AND EXISTS(
  SELECT 1 FROM pharmflow_expiry_private.photo_cleanup_jobs j WHERE j.object_path=NEW.photo_path AND j.state IN ('CLAIMED','DONE')) THEN
  RAISE EXCEPTION 'Photo cleanup already fenced; review cannot reference this image';
 END IF;
 RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION pharmflow_expiry_private.guard_receiving_storage_photo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v_path text;v_pharmacy uuid;v_review uuid;r public.pharmflow_needs_review_v2%rowtype;v_actor uuid;v_member boolean;v_sub text;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.bucket_id<>'pharmflow-needs-review' OR split_part(OLD.name,'/',2)='expiry-v1' THEN RETURN OLD; END IF;
  v_path:=OLD.name;
 ELSE
  IF TG_OP='UPDATE' AND (OLD.name IS DISTINCT FROM NEW.name OR OLD.bucket_id IS DISTINCT FROM NEW.bucket_id) AND
    (OLD.bucket_id='pharmflow-needs-review' OR NEW.bucket_id='pharmflow-needs-review') THEN
   RAISE EXCEPTION 'Review photos cannot move between scopes';
  END IF;
  IF NEW.bucket_id<>'pharmflow-needs-review' OR split_part(NEW.name,'/',2)='expiry-v1' THEN RETURN NEW; END IF;
  v_path:=NEW.name;
 END IF;
 IF v_path !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9]{10,20}[.](jpg|png|webp)$' THEN RAISE EXCEPTION 'Invalid Receiving photo path'; END IF;
 v_pharmacy:=split_part(v_path,'/',1)::uuid;v_review:=split_part(v_path,'/',2)::uuid;
 SELECT * INTO r FROM public.pharmflow_needs_review_v2 WHERE id=v_review AND pharmacy_id=v_pharmacy AND workflow='RECEIVING' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Receiving photo scope denied'; END IF;
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM public.pharmflow_needs_review_v2 a WHERE a.status='PENDING' AND a.photo_path=v_path) THEN RAISE EXCEPTION 'Active review photo is protected'; END IF;
  IF current_setting('role',true)='service_role' AND EXISTS(
   SELECT 1 FROM pharmflow_expiry_private.photo_cleanup_jobs j WHERE j.pharmacy_id=v_pharmacy AND j.review_id=v_review AND j.operation_id IS NULL AND j.object_path=v_path
   AND j.state='CLAIMED' AND j.claim_until>now() AND j.claim_token IS NOT NULL AND
   pharmflow_expiry_private.photo_cleanup_eligible(j.pharmacy_id,j.operation_id,j.review_id,j.object_path,j.cleanup_reason)) THEN RETURN OLD; END IF;
  IF r.status NOT IN ('RESOLVED','DELETED') OR public.is_pharmacy_admin(v_pharmacy) IS NOT TRUE THEN RAISE EXCEPTION 'Terminal Receiving photo deletion authorization required'; END IF;
  RETURN OLD;
 END IF;
 IF r.status<>'PENDING' THEN RAISE EXCEPTION 'Photo uploads require a pending Receiving review'; END IF;
 v_actor:=auth.uid();
 IF v_actor IS NULL AND session_user='supabase_storage_admin' AND current_setting('role',true)='service_role' THEN
  v_actor:=coalesce(NEW.owner_id,NEW.owner::text)::uuid;v_sub:=current_setting('request.jwt.claim.sub',true);
  PERFORM set_config('request.jwt.claim.sub',v_actor::text,true);v_member:=public.is_pharmacy_member(v_pharmacy);
  PERFORM set_config('request.jwt.claim.sub',coalesce(v_sub,''),true);
 ELSE v_member:=public.is_pharmacy_member(v_pharmacy); END IF;
 IF v_actor IS NULL OR v_member IS NOT TRUE OR coalesce(NEW.owner_id,NEW.owner::text) IS DISTINCT FROM v_actor::text THEN RAISE EXCEPTION 'Receiving photo actor denied'; END IF;
 RETURN NEW;
END $function$
;

